use strict; use warnings;
my $repo = "/bench/repo";
my $internal = "$repo/internal";

# collect decls
my @decls;
for my $path (glob("$internal/*/*.go"), glob("$internal/*/*/*.go"), glob("$internal/*/*/*/*.go"), glob("$internal/*.go")) {
  next unless $path =~ /\.go$/ && $path !~ /_test\.go$/;
  open my $fh, "<", $path or next;
  my $content = do { local $/; <$fh> };
  close $fh;
  my $rel = $path; $rel =~ s/^\Q$repo\E\///;
  my ($pkg) = $rel =~ m{internal/(?:[^/]+/)*([^/]+)/[^/]+\.go$};
  $pkg ||= (split /\//, $rel)[-1]; $pkg =~ s/\.go$//;

  while ($content =~ /^func\s+\((\w+)\s+\*?(\w+)\)\s+(\w+)\s*\(/gm) {
    push @decls, { qual => "$2.$3", short => $3, recv => $2, pkg => $pkg, path => $rel, method => 1 };
  }
  while ($content =~ /^func\s+(\w+)\s*\(/gm) {
    my $name = $1;
    push @decls, { qual => $name, short => $name, pkg => $pkg, path => $rel, method => 0 };
  }
}

# collect go files
my @gofiles;
require File::Find;
File::Find::find(sub {
  return unless -f && /\.go$/;
  return if $File::Find::name =~ m{/web/};
  return if $File::Find::name =~ m{/gen/};
  push @gofiles, $File::Find::name;
}, $repo);

my %counts;
for my $d (@decls) {
  my @patterns;
  push @patterns, qr/\b\Q$d->{short}\E\s*\(/;
  push @patterns, qr/\b\Q$d->{recv}\E\.\Q$d->{short}\E\s*\(/ if $d->{method};
  push @patterns, qr/\b\Q$d->{pkg}\E\.\Q$d->{short}\E\s*\(/;

  my %callers;
  for my $gf (@gofiles) {
    open my $fh, "<", $gf or next;
    my $c = do { local $/; <$fh> }; close $fh;
    my $matched = 0;
    for my $p (@patterns) { $matched = 1 if $c =~ /$p/; }
    next unless $matched;
    my $rel = $gf; $rel =~ s/^\Q$repo\E\///;
    if ($rel eq $d->{path}) {
      my $c2 = $c;
      $c2 =~ s/^func\s+(?:\([^)]+\)\s+)?\Q$d->{short}\E\s*\(//gm;
      $c2 =~ s/^func\s+\([^)]+\)\s+\Q$d->{short}\E\s*\(//gm;
      my $m2 = 0;
      for my $p (@patterns) { $m2 = 1 if $c2 =~ /$p/; }
      next unless $m2;
    }
    $callers{$rel} = 1;
  }
  $counts{"$d->{qual} @ $d->{path}"} = scalar keys %callers;
}

my $i = 0;
for my $k (sort { $counts{$b} <=> $counts{$a} || $a cmp $b } keys %counts) {
  print "$counts{$k}\t$k\n";
  last if ++$i >= 30;
}
'

